<template><aside v-if="route.path!=='/login' && user.user?.userId && !user.user.profile?.username && !dismissed" class="identity-claim"><span>{{ t('identityClaimHint') }}</span><el-button text @click="router.push('/settings')">{{ t('contactUsername') }}</el-button><button type="button" :aria-label="t('cancel')" @click="dismissed=true">×</button></aside></template>
<script setup>import {ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useI18n} from 'vue-i18n';import {useUserStore} from '@/store/user';const route=useRoute(),user=useUserStore(),router=useRouter(),{t}=useI18n(),dismissed=ref(false);watch(()=>user.user?.userId,()=>{dismissed.value=false;});</script>
<style scoped>.identity-claim{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);max-width:calc(100vw - 32px);width:440px;box-sizing:border-box;display:flex;align-items:center;gap:8px;padding:12px 16px;border:1px solid var(--el-border-color);border-radius:14px;background:var(--el-bg-color-overlay);box-shadow:var(--el-box-shadow-light);z-index:1800;font-size:12px;}.identity-claim>button{border:0;background:none;color:inherit;cursor:pointer;}</style>